test-case.test:
declare namespace a = "http://anno.com/";
declare namespace saxon = "http://saxon.sf.net/";
declare %a:colour("blue") %a:shape("circle", 2) %a:two-dimensional function local:f() as xs:integer {3};
saxon:function-annotations(local:f#0)

declare namespace a = "http://anno.com/";
declare namespace saxon = "http://saxon.sf.net/";
let $f := %a:colour("blue") %a:shape("circle", 2) %a:two-dimensional function () as xs:integer {3}
return saxon:function-annotations($f)

xquery version "3.1";
(:
 : Function annotations test
 : Use case: dumping out information on the anonymous function used into
 : embedded metadata
 :)

declare namespace this="http://www.w3.org/2005/xquery-local-functions";
declare namespace art="http://mathling.com/art";
declare namespace map="http://www.w3.org/2005/xpath-functions/map";
declare namespace saxon="http://saxon.sf.net/";

declare function this:times ($scale as xs:integer) as function(xs:double) as xs:double
{
  %art:name('times') function ($v as xs:double) as xs:double
  {
    $scale * $v
  }
};

declare %art:name("example") function this:example($x as xs:integer) as xs:integer
{
  $x + 1
};

let $f := this:example#1
let $g := this:times(10)
return (
  <art:metadata>
    <art:parameter name="example.f.name">{
    saxon:function-annotations($f)[map:get(.,"name")=xs:QName("art:name")]!map:get(.,"params")
    }</art:parameter>
    <art:parameter name="example.g.name">{
    saxon:function-annotations($g)[map:get(.,"name")=xs:QName("art:name")]!map:get(.,"params")
    }</art:parameter>
  </art:metadata>
)
